38	/**
39	 * This {@link LoadBalancer} selects an element using random and {@link WeightedObject#weight()}.
40	 * If there are A(weight 10), B(weight 4) and C(weight 6) elements, the chances that
41	 * elements are selected are 10/20, 4/20 and 6/20, respectively. If A is selected 10 times and B and C are not
42	 * selected as much as their weight, then A is removed temporarily and the chances that B and C are selected are
43	 * 4/10 and 6/10.
44	 */
45	final class WeightedRandomLoadBalancer<T> implements SimpleLoadBalancer<T> {
46	
47	    private final ReentrantLock lock = new ReentrantShortLock();
48	    private final List<CandidateContext<T>> allEntries;
49	    @GuardedBy("lock")
50	    private final List<CandidateContext<T>> currentEntries;
51	    private final long total;
52	    private long remaining;
53	
54	    WeightedRandomLoadBalancer(Iterable<? extends T> candidates,
55	                               @Nullable ToIntFunction<? super T> weightFunction) {
56	        @SuppressWarnings("unchecked")
57	        final List<CandidateContext<T>> candidateContexts =
58	                Streams.stream((Iterable<T>) candidates)
59	                       .map(e -> {
60	                           if (weightFunction == null) {
61	                               return new CandidateContext<>(e, ((Weighted) e).weight());
62	                           } else {
63	                               return new CandidateContext<>(e, weightFunction.applyAsInt(e));
64	                           }
65	                       })
66	                       .filter(e -> e.weight() > 0)
67	                       .collect(toImmutableList());
68	
69	        total = candidateContexts.stream().mapToLong(CandidateContext::weight).sum();
70	        remaining = total;
71	        allEntries = candidateContexts;
72	        currentEntries = new ArrayList<>(allEntries);
73	    }
74	
75	    @VisibleForTesting
76	    List<CandidateContext<T>> entries() {
77	        return allEntries;
78	    }
79	
80	    @Nullable
81	    @Override
82	    public T pick() {
83	        if (allEntries.isEmpty()) {
84	            return null;
85	        }
86	
87	        final ThreadLocalRandom threadLocalRandom = ThreadLocalRandom.current();
88	        lock.lock();
89	        try {
90	            long target = threadLocalRandom.nextLong(remaining);
91	            final Iterator<CandidateContext<T>> it = currentEntries.iterator();
92	            while (it.hasNext()) {
93	                final CandidateContext<T> entry = it.next();
94	                final int weight = entry.weight();
95	                target -= weight;
96	                if (target < 0) {
97	                    entry.increment();
98	                    if (entry.isFull()) {
99	                        it.remove();
100	                        entry.reset();
101	                        remaining -= weight;
102	                        if (remaining == 0) {
103	                            // As all entries are full, reset `currentEntries` and `remaining`.
104	                            currentEntries.addAll(allEntries);
105	                            remaining = total;
106	                        } else {
107	                            assert remaining > 0 : remaining;
108	                        }
109	                    }
110	                    return entry.get();
111	                }
112	            }
113	        } finally {
114	            lock.unlock();
115	        }
116	
117	        // Since `allEntries` is not empty, should subselect one Endpoint from `allEntries`.
118	        throw new Error("Should never reach here");
119	    }
120	
121	    @SuppressWarnings("GuardedBy")
122	    @Override
123	    public String toString() {
124	        return MoreObjects.toStringHelper(this)
125	                          .add("allEntries", allEntries)
126	                          .add("currentEntries", currentEntries)
127	                          .add("total", total)
128	                          .add("remaining", remaining)
129	                          .toString();
130	    }
131	
132	    @VisibleForTesting
133	    static final class CandidateContext<T> extends WeightedObject<T> {
134	
135	        private int counter;
136	
137	        CandidateContext(T candidate, int weight) {
138	            super(candidate, weight);
139	        }
140	
141	        void increment() {
142	            assert counter < weight();
143	            counter++;
144	        }
145	
146	        void reset() {
147	            counter = 0;
148	        }
149	
150	        int counter() {
151	            return counter;
152	        }
153	
154	        boolean isFull() {
155	            return counter >= weight();
156	        }
157	    }
158	}
